const FB_POST_LIST_FIELDS = [
  "id",
  "message",
  "created_time",
  "permalink_url",
  "full_picture",
  "shares",
  // summary(true) for list counts; stream filter on the comments edge is used when fetching threads.
  "comments.summary(true)",
  "reactions.summary(true)",
  "attachments{media_type,type,url,media,target}",
].join(",");
const FB_POST_LIST_FIELDS_MIN = [
  "id",
  "message",
  "created_time",
  "permalink_url",
  "full_picture",
  "attachments{media_type,type,url,media,target}",
].join(",");

async function fetchFacebookPostsFromEndpoint(
  endpoint: string,
  accessToken: string,
  limit: number,
  dateRange?: { startYmd: string; endYmd: string },
  options?: { allTime?: boolean },
): Promise<{ posts: MetaContentPost[]; sawAnyBatch: boolean }> {
  const filterByDate = Boolean(
    dateRange?.startYmd && dateRange?.endYmd && !options?.allTime,
  );
  const paginate = filterByDate || options?.allTime === true;
  const inRange: MetaContentPost[] = [];
  let after: string | undefined;
  const maxPages = options?.allTime ? META_CONTENT_ALL_TIME_MAX_PAGES : filterByDate ? 25 : 1;
  const cap = options?.allTime ? META_CONTENT_ALL_TIME_MAX_POSTS : limit;
  let sawAnyBatch = false;

  for (let page = 0; page < maxPages && inRange.length < cap; page++) {
    const params: Record<string, string> = {
      limit: paginate ? "50" : String(Math.min(Math.max(limit, 1), 100)),
    };
    if (after) params.after = after;

    const load = (fields: string) =>
      graphGet<{
        data?: Array<Record<string, unknown>>;
        paging?: { cursors?: { after?: string } };
      }>(graphUrl(endpoint, { ...params, fields }), accessToken);
    let data: Awaited<ReturnType<typeof load>>;
    try {
      data = await load(FB_POST_LIST_FIELDS);
    } catch (err) {
      if (!isUnknownGraphFieldError(err)) throw err;
      data = await load(FB_POST_LIST_FIELDS_MIN);
    }

    const batch = (data.data ?? []).map(mapFbPost);
    if (batch.length === 0) break;
    sawAnyBatch = true;

    if (!paginate) {
      return { posts: batch.slice(0, limit), sawAnyBatch: true };
    }

    const { startYmd = "", endYmd = "" } = dateRange ?? {};
    for (const post of batch) {
      if (filterByDate) {
        if (!post.timestamp) continue;
        const ymd = timestampToUtcYmd(post.timestamp);
        if (!ymd || ymd < startYmd || ymd > endYmd) continue;
      }
      inRange.push(post);
      if (inRange.length >= cap) break;
    }

    if (filterByDate && startYmd) {
      const oldest = batch[batch.length - 1];
      const oldestYmd = oldest?.timestamp ? timestampToUtcYmd(oldest.timestamp) : "";
      if (oldestYmd && oldestYmd < startYmd) break;
    }

    after = data.paging?.cursors?.after;
    if (!after) break;
  }

  return { posts: inRange, sawAnyBatch };
}

export type ResolveFacebookPostsOptions = {
  allTime?: boolean;
  /** Throw the last Graph error when every feed endpoint fails. */
  surfaceErrors?: boolean;
};

/**
 * Fetches Facebook page posts, optionally paginating until enough posts fall in the YMD range.
 */
export async function resolveFacebookPostsForMetrics(
  pageId: string,
  accessToken: string,
  limit: number,
  dateRange?: { startYmd: string; endYmd: string },
  options?: ResolveFacebookPostsOptions,
): Promise<MetaContentPost[]> {
  const listEndpoints = [
    `${pageId}/published_posts`,
    `${pageId}/posts`,
    `${pageId}/feed`,
  ];
  let lastError: unknown = null;

  for (const endpoint of listEndpoints) {
    try {
      const { posts, sawAnyBatch } = await fetchFacebookPostsFromEndpoint(
        endpoint,
        accessToken,
        limit,
        dateRange,
        options,
      );
      if (posts.length > 0) return posts;
      if (sawAnyBatch) return [];
    } catch (err) {
      lastError = err;
      console.warn(`resolveFacebookPostsForMetrics ${endpoint}:`, err instanceof Error ? err.message : err);
    }
  }

  if (options?.surfaceErrors && lastError) {
    throw lastError instanceof Error ? lastError : new Error(String(lastError));
  }

  return [];
}

export async function fetchFacebookPosts(
  pageId: string,
  accessToken: string,
  limit = 25,
): Promise<MetaContentPost[]> {
  return resolveFacebookPostsForMetrics(pageId, accessToken, limit);
}

async function fetchFacebookAdsPostsEdge(
  pageId: string,
  accessToken: string,
  limit: number,
): Promise<MetaContentPost[]> {
  // Keep to one page — Manage Comments must stay under edge worker time budget.
  const data = await graphGet<{
    data?: Array<Record<string, unknown>>;
  }>(
    graphUrl(`${pageId}/ads_posts`, {
      fields: FB_POST_LIST_FIELDS,
      limit: String(Math.min(Math.max(limit, 1), 25)),
      include_inline_create: "true",
    }),
    accessToken,
  );
  return (data.data ?? []).map(mapFbPost).slice(0, limit);
}

async function collectFacebookAdStoryIdsForPage(
  adsUserToken: string,
  adAccountIds: string[],
  pageId: string,
  maxIds: number,
): Promise<string[]> {
  const ids: string[] = [];
  const seen = new Set<string>();
  const pagePrefix = `${pageId}_`;
  const filtering = JSON.stringify([
    {
      field: "effective_status",
      operator: "IN",
      value: ["ACTIVE", "PAUSED", "CAMPAIGN_PAUSED", "ADSET_PAUSED"],
    },
  ]);

  for (const raw of adAccountIds) {
    if (ids.length >= maxIds) break;
    const digits = String(raw ?? "").replace(/\D/g, "");
    if (!digits) continue;
    try {
      const data = await graphGet<{
        data?: Array<Record<string, unknown>>;
      }>(
        graphUrl(`act_${digits}/ads`, {
          fields: "id,creative{effective_object_story_id,object_story_id}",
          limit: "25",
          filtering,
        }),
        adsUserToken,
      );

      for (const ad of data.data ?? []) {
        const creative = ad.creative as Record<string, unknown> | undefined;
        const storyId = String(
          creative?.effective_object_story_id ?? creative?.object_story_id ?? "",
        ).trim();
        if (!storyId || seen.has(storyId)) continue;
        if (!storyId.startsWith(pagePrefix)) continue;
        seen.add(storyId);
        ids.push(storyId);
        if (ids.length >= maxIds) break;
      }
    } catch (err) {
      console.warn(
        "[metaContent] collectFacebookAdStoryIdsForPage act_",
        digits,
        err instanceof Error ? err.message : err,
      );
    }
  }
  return ids;
}

async function hydrateFacebookPostsByIds(
  ids: string[],
  accessToken: string,
): Promise<MetaContentPost[]> {
  if (ids.length === 0) return [];
  const relativeUrls = ids.slice(0, 25).map(
    (id) => `${encodeURIComponent(id)}?fields=${encodeURIComponent(FB_POST_LIST_FIELDS)}`,
  );
  const results = await graphBatchGet(accessToken, relativeUrls);
  const posts: MetaContentPost[] = [];
  for (const item of results) {
    if (!isGraphBatchItemSuccess(item)) continue;
    try {
      const body = JSON.parse(item.body) as Record<string, unknown> & GraphError;
      if (body?.error) continue;
      const post = mapFbPost(body);
      if (post.id) posts.push(post);
    } catch {
      // skip malformed batch body
    }
  }
  return posts;
}

export type FetchFacebookAdsPostsResult = {
  posts: MetaContentPost[];
  source: "ads_posts" | "marketing_api" | "none";
  warnings: string[];
};

/**
 * Facebook ads-only / dark posts for Manage Comments.
 * Fast path: Page `ads_posts` (1 request). Fallback: Marketing API story IDs for this page.
 */
export async function fetchFacebookAdsPosts(args: {
  pageId: string;
  pageAccessToken: string;
  adsUserToken?: string | null;
  adAccountIds?: string[];
  limit?: number;
}): Promise<FetchFacebookAdsPostsResult> {
  const limit = Math.min(Math.max(args.limit ?? 25, 1), 25);
  const seen = new Set<string>();
  const out: MetaContentPost[] = [];
  const warnings: string[] = [];
  let source: FetchFacebookAdsPostsResult["source"] = "none";

  const pushPosts = (posts: MetaContentPost[], from: FetchFacebookAdsPostsResult["source"]) => {
    for (const p of posts) {
      if (!p.id || seen.has(p.id)) continue;
      if (p.id.includes("_") && !p.id.startsWith(`${args.pageId}_`) && p.id !== args.pageId) {
        continue;
      }
      seen.add(p.id);
      out.push({ ...p, is_ad: true });
      if (source === "none") source = from;
      if (out.length >= limit) break;
    }
  };

  const adsToken = args.adsUserToken?.trim() || "";
  if (!adsToken) {
    warnings.push("meta_ads_not_connected");
  }

  // 1) Prefer ads_posts (cheap) with ads token, then page token.
  const tokensToTry = [adsToken, args.pageAccessToken].filter(Boolean);
  for (const token of tokensToTry) {
    if (out.length >= limit) break;
    try {
      pushPosts(await fetchFacebookAdsPostsEdge(args.pageId, token, limit), "ads_posts");
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      warnings.push(`ads_posts: ${msg}`);
      console.warn("[metaContent] ads_posts failed:", msg);
    }
  }

  // 2) Light Marketing API fallback only if ads_posts returned nothing.
  if (out.length === 0 && adsToken && (args.adAccountIds?.length ?? 0) > 0) {
    try {
      const storyIds = await collectFacebookAdStoryIdsForPage(
        adsToken,
        args.adAccountIds ?? [],
        args.pageId,
        limit,
      );
      if (storyIds.length > 0) {
        let hydrated = await hydrateFacebookPostsByIds(storyIds, args.pageAccessToken);
        if (hydrated.length === 0) {
          hydrated = await hydrateFacebookPostsByIds(storyIds, adsToken);
        }
        pushPosts(hydrated, "marketing_api");
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      warnings.push(`marketing_api: ${msg}`);
      console.warn("[metaContent] ads story hydrate failed:", msg);
    }
  }

  return { posts: out.slice(0, limit), source, warnings };
}

/** Merge organic page posts with ads/dark posts; ads wins on duplicate IDs. */
export function mergeFacebookOrganicAndAdsPosts(
  organic: MetaContentPost[],
  ads: MetaContentPost[],
): MetaContentPost[] {
  const byId = new Map<string, MetaContentPost>();
  for (const p of organic) {
    if (!p.id) continue;
    byId.set(p.id, { ...p, is_ad: Boolean(p.is_ad) });
  }
  for (const p of ads) {
    if (!p.id) continue;
    const existing = byId.get(p.id);
    byId.set(p.id, existing ? { ...existing, ...p, is_ad: true } : { ...p, is_ad: true });
  }
  return Array.from(byId.values()).sort((a, b) => {
    const aT = a.timestamp ? new Date(a.timestamp).getTime() : 0;
    const bT = b.timestamp ? new Date(b.timestamp).getTime() : 0;
    return bT - aT;
  });
}

function looksLikeVideoUrl(url: string): boolean {
  return /\.(mp4|mov|webm|m4v)(\?|$)/i.test(url) || /\/video\//i.test(url);
}

/** URL suitable for <img> preview — Reels/VIDEO must use thumbnail, not MP4 media_url. */
export function pickInstagramPostPreviewUrl(
  p: Pick<MetaContentPost, "media_type" | "media_url" | "thumbnail_url">,
): string | null {
  const thumb = p.thumbnail_url?.trim() || null;
  const media = p.media_url?.trim() || null;
  const type = (p.media_type ?? "").toUpperCase();

  if (type === "VIDEO" || type === "REELS" || type === "STORY") {
    return thumb;
  }
  if (media && looksLikeVideoUrl(media)) {
    return thumb;
  }
  return media ?? thumb;
}

function mapIgMedia(row: Record<string, unknown>): MetaContentPost {
  return {
    id: String(row.id ?? ""),
    caption: typeof row.caption === "string" ? row.caption : null,
    media_type: typeof row.media_type === "string" ? row.media_type : null,
    media_product_type: typeof row.media_product_type === "string" ? row.media_product_type : null,
    media_url: typeof row.media_url === "string" ? row.media_url : null,
    thumbnail_url: typeof row.thumbnail_url === "string" ? row.thumbnail_url : null,
    permalink: typeof row.permalink === "string" ? row.permalink : null,
    timestamp: typeof row.timestamp === "string" ? row.timestamp : null,
    comment_count: Number(row.comments_count ?? 0),
    like_count: Number(row.like_count ?? 0),
    shares_count: Number(row.shares_count ?? 0) || 0,
  };
}

function parseFbInlineInsights(row: Record<string, unknown>): { views: number; reach: number } {
  const insights = row.insights as { data?: FbInsightMetricRow[] } | undefined;
  const out: Record<string, number> = {};
  for (const metric of insights?.data ?? []) {
    out[String(metric.name ?? "")] = parseFbInsightMetricValue(metric);
  }
  return {
    views: out.post_media_view ?? out.post_impressions ?? 0,
    reach: out.post_total_media_view_unique ?? out.post_impressions_unique ?? 0,
  };
}

function firstFbAttachment(row: Record<string, unknown>): Record<string, unknown> | null {
  const attachments = row.attachments as { data?: Record<string, unknown>[] } | undefined;
  const first = attachments?.data?.[0];
  return first && typeof first === "object" ? first : null;
}

function isFacebookVideoAttachment(attachment: Record<string, unknown> | null): boolean {
  if (!attachment) return false;
  const type = String(attachment.type ?? attachment.media_type ?? "").toLowerCase();
  return type.includes("video");
}

function facebookAttachmentMediaSource(attachment: Record<string, unknown> | null): string | null {
  if (!attachment) return null;
  const media = attachment.media as { source?: unknown; image?: { src?: unknown } } | undefined;
  return typeof media?.source === "string" && media.source.trim() ? media.source : null;
}

function facebookAttachmentImageSrc(attachment: Record<string, unknown> | null): string | null {
  if (!attachment) return null;
  const media = attachment.media as { image?: { src?: unknown } } | undefined;
  return typeof media?.image?.src === "string" && media.image.src.trim()
    ? media.image.src
    : null;
}

function mapFbPost(row: Record<string, unknown>): MetaContentPost {
  const comments = row.comments as { summary?: { total_count?: number } } | undefined;
  const reactions = row.reactions as { summary?: { total_count?: number } } | undefined;
  const likes = row.likes as { summary?: { total_count?: number } } | undefined;
  const inline = parseFbInlineInsights(row);
  const shares = row.shares as { count?: number } | undefined;
  const attachment = firstFbAttachment(row);
  const isVideo = isFacebookVideoAttachment(attachment);
  const picture =
    (typeof row.full_picture === "string" ? row.full_picture : null) ??
    facebookAttachmentImageSrc(attachment);
  const videoSource = facebookAttachmentMediaSource(attachment);
  return {
    id: String(row.id ?? ""),
    caption: typeof row.message === "string" ? row.message : null,
    media_type: isVideo ? "VIDEO" : "post",
    media_url: videoSource ?? (isVideo ? null : picture),
    thumbnail_url: picture,
    permalink: typeof row.permalink_url === "string" ? row.permalink_url : null,
    timestamp: typeof row.created_time === "string" ? row.created_time : null,
    comment_count: Number(comments?.summary?.total_count ?? 0),
    like_count: Number(
      reactions?.summary?.total_count ?? likes?.summary?.total_count ?? 0,
    ),
    shares_count: Number(shares?.count ?? 0) || 0,
    insight_views: inline.views > 0 ? inline.views : undefined,
    insight_reach: inline.reach > 0 ? inline.reach : undefined,
  };
}

export type MetaMediaPreview = {
  caption: string | null;
  thumbnail_url: string | null;
  permalink: string | null;
};

/** Fetch caption/thumbnail for a single IG or FB post by media/post id. */
export async function fetchMetaMediaPreviewById(
  mediaId: string,
  platform: MetaContentPlatform,
  accessToken: string,
): Promise<MetaMediaPreview | null> {
  const id = mediaId.trim();
  if (!id) return null;
  try {
    if (platform === "instagram") {
      const data = await graphGet<Record<string, unknown>>(
        graphUrl(id, { fields: "caption,media_type,media_url,thumbnail_url,permalink" }),
        accessToken,
      );
      const post = mapIgMedia(data);
      return {
        caption: post.caption,
        thumbnail_url: pickInstagramPostPreviewUrl(post),
        permalink: post.permalink,
      };
    }
    const data = await graphGet<Record<string, unknown>>(
      graphUrl(id, { fields: "message,full_picture,permalink_url" }),
      accessToken,
    );
    const post = mapFbPost(data);
    return {
      caption: post.caption,
      thumbnail_url: post.thumbnail_url ?? post.media_url,
      permalink: post.permalink,
    };
  } catch (err) {
    console.warn("[metaContent] fetchMetaMediaPreviewById failed:", id, platform, err);
    return null;
  }
}

export async function fetchInstagramComments(
  mediaId: string,
  accessToken: string,
): Promise<MetaContentComment[]> {
  const fields = "id,text,username,timestamp,like_count,replies{id,text,username,timestamp,like_count}";
  const url = graphUrl(`${mediaId}/comments`, { fields });
  const data = await graphGet<{ data?: Array<Record<string, unknown>> }>(url, accessToken);
  const topLevel = (data.data ?? []).flatMap((row) => {
    const parentId = String(row.id ?? "");
    const replies = row.replies as { data?: Array<Record<string, unknown>> } | undefined;
    const replyRows = (replies?.data ?? []).map((r) => mapIgComment(r, mediaId, parentId));
    const parent = mapIgComment(row, mediaId, null, replyRows.length);
    return [parent, ...replyRows];
  });
  return topLevel;
}

function mapIgComment(
  row: Record<string, unknown>,
  mediaId: string,
  parentId: string | null,
  replyCount = 0,
): MetaContentComment {
  return {
    id: String(row.id ?? ""),
    media_id: mediaId,
    text: typeof row.text === "string" ? row.text : "",
    author_name: typeof row.username === "string" ? row.username : "Unknown",
    author_id: null,
    like_count: Number(row.like_count ?? 0),
    reply_count: parentId ? 0 : replyCount,
    parent_comment_id: parentId,
    published_at: typeof row.timestamp === "string" ? row.timestamp : null,
    is_owner: false,
    can_reply: true,
  };
}

async function fetchFacebookCommentsWithFilter(
  postId: string,
  accessToken: string,
  filter: "stream" | "toplevel",
): Promise<MetaContentComment[]> {
  // Keep fields flat — nested comments{} + filter=stream often returns empty for ads/dark posts.
  // Request `from` (not only from{id,name}) — Meta often omits author for public
  // users until Business Asset User Profile Access + Advanced Access are approved.
  const fields = "id,message,from,created_time,like_count,comment_count,parent";
  const data = await graphGet<{ data?: Array<Record<string, unknown>> }>(
    graphUrl(`${postId}/comments`, {
      fields,
      filter,
      order: "reverse_chronological",
      limit: "100",
    }),
    accessToken,
  );
  const mapped = (data.data ?? []).map((row) => {
    const parentObj = row.parent as { id?: string } | undefined;
    const parentId =
      typeof parentObj?.id === "string" && parentObj.id.trim() ? parentObj.id.trim() : null;
    return mapFbComment(row, postId, parentId);
  });
  if (mapped.length > 0) {
    const named = mapped.filter((c) => c.author_name.trim().length > 0).length;
    console.info(
      `[metaContent] facebook comments filter=${filter} post=${postId}: ${named}/${mapped.length} with from.name`,
    );
  }
  return mapped;
}

export async function fetchFacebookComments(
  postId: string,
  accessToken: string,
): Promise<MetaContentComment[]> {
  // Prefer stream (ads / moderation set), fall back to toplevel if stream fails or is empty.
  try {
    const streamed = await fetchFacebookCommentsWithFilter(postId, accessToken, "stream");
    if (streamed.length > 0) return streamed;
  } catch (err) {
    console.warn(
      "[metaContent] facebook comments stream failed:",
      err instanceof Error ? err.message : err,
    );
  }
  try {
    return await fetchFacebookCommentsWithFilter(postId, accessToken, "toplevel");
  } catch (err) {
    console.warn(
      "[metaContent] facebook comments toplevel failed:",
      err instanceof Error ? err.message : err,
    );
    throw err;
  }
}

function mapFbComment(
  row: Record<string, unknown>,
  mediaId: string,
  parentId: string | null,
): MetaContentComment {
  const from = row.from as { id?: string; name?: string } | undefined;
  const authorName =
    typeof from?.name === "string" && from.name.trim() ? from.name.trim() : "";
  const authorId = typeof from?.id === "string" && from.id.trim() ? from.id.trim() : null;
  return {
    id: String(row.id ?? ""),
    media_id: mediaId,
    text: typeof row.message === "string" ? row.message : "",
    // Empty when Meta withholds `from` (needs App Review: Business Asset User Profile Access).
    author_name: authorName,
    author_id: authorId,
    like_count: Number(row.like_count ?? 0),
    reply_count: Number(row.comment_count ?? 0),
    parent_comment_id: parentId,
    published_at: typeof row.created_time === "string" ? row.created_time : null,
    is_owner: false,
    can_reply: true,
  };
}

