function mapThreadsReply(
  row: Record<string, unknown>,
  fetchTargetId: string,
  parentId: string | null,
): ThreadsComment {
  const repliedTo = row.replied_to as { id?: string } | undefined;
  const rootPost = row.root_post as { id?: string } | undefined;
  const rootId = rootPost?.id ? String(rootPost.id) : fetchTargetId;
  const parent = parentId ?? (repliedTo?.id ? String(repliedTo.id) : null);
  return {
    id: String(row.id ?? ""),
    media_id: rootId,
    text: typeof row.text === "string" ? row.text : "",
    author_name: typeof row.username === "string" ? row.username : "Unknown",
    author_id: null,
    reply_count: Number(row.reply_count ?? 0),
    parent_comment_id: parent,
    published_at: typeof row.timestamp === "string" ? row.timestamp : null,
    is_owner: Boolean(row.is_reply_owned_by_me),
    can_reply: true,
  };
}

const THREADS_REPLY_FIELDS =
  "id,text,username,timestamp,reply_count,replied_to,root_post,is_reply,is_reply_owned_by_me,hide_status,has_replies";

function dedupeThreadsCommentsById(comments: ThreadsComment[]): ThreadsComment[] {
  const seen = new Set<string>();
  const out: ThreadsComment[] = [];
  for (const row of comments) {
    const id = String(row.id ?? "").trim();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(row);
  }
  return out;
}

export function buildTopLevelCommentsFromConversation(
  conversation: ThreadsComment[],
  postMediaId: string,
): ThreadsComment[] {
  const postId = String(postMediaId ?? "").trim();
  return conversation.filter(
    (c) => c.id !== postId && (!c.parent_comment_id || c.parent_comment_id === postId),
  );
}

export function enrichTopLevelReplyCountsFromConversation(
  topLevel: ThreadsComment[],
  conversation: ThreadsComment[],
): ThreadsComment[] {
  return topLevel.map((comment) => enrichCommentReplyCountFromConversation(comment, conversation));
}

export function enrichCommentReplyCountFromConversation(
  comment: ThreadsComment,
  conversation: ThreadsComment[],
): ThreadsComment {
  const nestedCount = conversation.filter((c) => c.parent_comment_id === comment.id).length;
  return { ...comment, reply_count: Math.max(comment.reply_count, nestedCount) };
}

export function enrichReplyCountsFromConversation(
  replies: ThreadsComment[],
  conversation: ThreadsComment[],
): ThreadsComment[] {
  return replies.map((reply) => enrichCommentReplyCountFromConversation(reply, conversation));
}

export function countConversationActivity(
  conversation: ThreadsComment[],
  postMediaId: string,
): number {
  const postId = String(postMediaId ?? "").trim();
  return conversation.filter((c) => c.id !== postId).length;
}

export function filterNestedRepliesFromConversation(
  conversation: ThreadsComment[],
  parentCommentId: string,
): ThreadsComment[] {
  const parentId = String(parentCommentId ?? "").trim();
  return conversation.filter((c) => c.parent_comment_id === parentId);
}

async function fetchThreadPendingReplies(
  postMediaId: string,
  accessToken: string,
): Promise<ThreadsComment[]> {
  const postId = String(postMediaId ?? "").trim();
  if (!postId) return [];
  try {
    const data = await threadsGet<{ data?: Array<Record<string, unknown>> }>(
      threadsUrl(`${postId}/pending_replies`, { fields: THREADS_REPLY_FIELDS, limit: "25" }),
      accessToken,
    );
    return (data.data ?? []).map((row) => mapThreadsReply(row, postId, null));
  } catch {
    return [];
  }
}

/** Flattened top-level + nested replies — includes replies created in the Threads app. */
export async function fetchThreadConversation(
  postMediaId: string,
  accessToken: string,
  maxPages = 12,
): Promise<ThreadsComment[]> {
  const postId = String(postMediaId ?? "").trim();
  if (!postId) return [];

  const all: ThreadsComment[] = [];
  let after: string | undefined;
  let conversationSupported = true;

  for (let page = 0; page < maxPages; page++) {
    const params: Record<string, string> = {
      fields: THREADS_REPLY_FIELDS,
      limit: "25",
    };
    if (after) params.after = after;

    try {
      const data = await threadsGet<{
        data?: Array<Record<string, unknown>>;
        paging?: { cursors?: { after?: string } };
      }>(threadsUrl(`${postId}/conversation`, params), accessToken);
      const batch = (data.data ?? []).map((row) => mapThreadsReply(row, postId, null));
      all.push(...batch);
      after = data.paging?.cursors?.after;
      if (!after || batch.length === 0) break;
    } catch (e) {
      conversationSupported = false;
      console.warn("fetchThreadConversation fallback:", postId, e);
      break;
    }
  }

  if (!conversationSupported && all.length === 0) {
    const topLevel = await fetchThreadRepliesPaginated(postId, accessToken, maxPages);
    const pending = await fetchThreadPendingReplies(postId, accessToken);
    return dedupeThreadsCommentsById([...topLevel, ...pending]);
  }

  const pending = await fetchThreadPendingReplies(postId, accessToken);
  return dedupeThreadsCommentsById([...all, ...pending]);
}

export async function fetchThreadRepliesPaginated(
  mediaId: string,
  accessToken: string,
  maxPages = 8,
): Promise<ThreadsComment[]> {
  const targetId = String(mediaId ?? "").trim();
  if (!targetId) return [];

  const all: ThreadsComment[] = [];
  let after: string | undefined;

  for (let page = 0; page < maxPages; page++) {
    const params: Record<string, string> = {
      fields: THREADS_REPLY_FIELDS,
      limit: "25",
    };
    if (after) params.after = after;

    try {
      const data = await threadsGet<{
        data?: Array<Record<string, unknown>>;
        paging?: { cursors?: { after?: string } };
      }>(threadsUrl(`${targetId}/replies`, params), accessToken);
      const batch = (data.data ?? []).map((row) => mapThreadsReply(row, targetId, null));
      all.push(...batch);
      after = data.paging?.cursors?.after;
      if (!after || batch.length === 0) break;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      if (
        /does not exist|unsupported get request|nonexisting|\(#100\)/i.test(msg) ||
        /missing permissions|\(#10\)|\(#200\)/i.test(msg)
      ) {
        console.warn("fetchThreadRepliesPaginated soft-empty:", targetId, msg);
        break;
      }
      throw e;
    }
  }

  return dedupeThreadsCommentsById(all);
}

export async function fetchThreadReplies(
  mediaId: string,
  accessToken: string,
): Promise<ThreadsComment[]> {
  return fetchThreadRepliesPaginated(mediaId, accessToken, 4);
}

/** Prefer full conversation tree; fall back to per-comment /replies. */
export async function fetchThreadNestedReplies(
  postMediaId: string,
  parentCommentId: string,
  accessToken: string,
): Promise<ThreadsComment[]> {
  const parentId = String(parentCommentId ?? "").trim();
  const postId = String(postMediaId ?? "").trim();
  if (!parentId) return [];

  const conversation = postId ? await fetchThreadConversation(postId, accessToken) : [];
  const fromConversation = filterNestedRepliesFromConversation(conversation, parentId);
  if (fromConversation.length > 0) return fromConversation;

  const direct = await fetchThreadRepliesPaginated(parentId, accessToken);
  if (direct.length > 0) {
    return direct.map((row) => ({
      ...row,
      parent_comment_id: row.parent_comment_id === parentId ? row.parent_comment_id : parentId,
    }));
  }

  if (!postId || parentId === postId) return [];

  const topLevel = await fetchThreadRepliesPaginated(postId, accessToken);
  return topLevel.filter((row) => row.parent_comment_id === parentId);
}

export async function enrichThreadsTopLevelCommentsWithReplyCounts(
  comments: ThreadsComment[],
  accessToken: string,
  postMediaId?: string,
): Promise<ThreadsComment[]> {
  const postId = String(postMediaId ?? comments[0]?.media_id ?? "").trim();
  if (postId) {
    const conversation = await fetchThreadConversation(postId, accessToken);
    const topLevel = buildTopLevelCommentsFromConversation(conversation, postId);
    const enriched = enrichTopLevelReplyCountsFromConversation(topLevel, conversation);
    const enrichedById = new Map(enriched.map((c) => [c.id, c]));
    return comments.map((c) => enrichedById.get(c.id) ?? c);
  }

  const batchSize = 8;
  const enriched: ThreadsComment[] = [];
  for (let i = 0; i < comments.length; i += batchSize) {
    const chunk = comments.slice(i, i + batchSize);
    const rows = await Promise.all(
      chunk.map(async (comment) => {
        try {
          const nested = await fetchThreadRepliesPaginated(comment.id, accessToken, 4);
          return { ...comment, reply_count: Math.max(comment.reply_count, nested.length) };
        } catch {
          return comment;
        }
      }),
    );
    enriched.push(...rows);
  }
  return enriched;
}

export async function fetchThreadsRepliedToId(
  mediaOrReplyId: string,
  accessToken: string,
): Promise<string | null> {
  try {
    const data = await threadsGet<{ replied_to?: { id?: string } }>(
      threadsUrl(`${mediaOrReplyId}`, { fields: "replied_to" }),
      accessToken,
    );
    const parent = data.replied_to?.id != null ? String(data.replied_to.id).trim() : "";
    return parent || null;
  } catch {
    return null;
  }
}

/** Walk replied_to chain to find the root post/media id for /{id}/replies. */
export async function resolveThreadsPostIdFromReplyChain(
  startId: string,
  accessToken: string,
  maxHops = 5,
): Promise<string | null> {
  let current = String(startId ?? "").trim();
  if (!current) return null;
  for (let hop = 0; hop < maxHops; hop++) {
    const parent = await fetchThreadsRepliedToId(current, accessToken);
    if (!parent || parent === current) return current;
    current = parent;
  }
  return current;
}

export function extractRootPostIdFromRawMetadata(raw: unknown): string | null {
  if (!raw || typeof raw !== "object") return null;
  const meta = raw as Record<string, unknown>;
  const values = meta.values as { value?: Record<string, unknown> } | undefined;
  const rootPost = values?.value?.root_post as { id?: unknown } | undefined;
  if (rootPost?.id != null && String(rootPost.id).trim()) {
    return String(rootPost.id).trim();
  }
  return null;
}

export async function resolveThreadsPostMediaIdForReply(
  admin: import("https://esm.sh/@supabase/supabase-js@2").SupabaseClient,
  conversationId: string,
  storedRootMediaId: string,
  accessToken: string,
  replyToCommentId?: string | null,
): Promise<string> {
  let root = String(storedRootMediaId ?? "").trim();
  const replyTo = replyToCommentId?.trim() ?? "";

  const { data: msgRows } = await admin
    .from("threads_messages")
    .select("raw_metadata")
    .eq("conversation_id", conversationId)
    .order("created_at", { ascending: true })
    .limit(10);

  for (const row of msgRows ?? []) {
    const fromMeta = extractRootPostIdFromRawMetadata(
      (row as { raw_metadata?: unknown }).raw_metadata,
    );
    if (fromMeta) {
      root = fromMeta;
      break;
    }
  }

  if (!root || (replyTo && root === replyTo)) {
    const seed = replyTo || root || storedRootMediaId;
    const resolved = await resolveThreadsPostIdFromReplyChain(seed, accessToken);
    if (resolved) root = resolved;
  }

  if (root && root !== storedRootMediaId) {
    await admin
      .from("threads_conversations")
      .update({ root_media_id: root, updated_at: new Date().toISOString() })
      .eq("id", conversationId);
  }

  return root || storedRootMediaId;
}

async function threadsPostStep<T>(
  step: "create_reply_container" | "publish_reply",
  url: string,
  accessToken: string,
  body: Record<string, string>,
): Promise<T> {
  try {
    return await threadsPost<T>(url, accessToken, body);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    if (/does not have permission/i.test(msg)) {
      const hint = step === "publish_reply"
        ? "threads_content_publish"
        : "threads_manage_replies (and threads_content_publish for nested replies)";
      throw new Error(`${msg} (${step}: requires ${hint} on the Threads access token)`);
    }
    throw e;
  }
}

async function publishThreadsReplyContainer(
  creationId: string,
  accessToken: string,
  threadsUserId?: string,
): Promise<{ id: string }> {
  const publishPaths = ["me/threads_publish"];
  const explicitUserId = threadsUserId?.trim();
  if (explicitUserId) publishPaths.push(`${explicitUserId}/threads_publish`);

  let lastError: Error | null = null;
  for (const path of publishPaths) {
    try {
      const published = await threadsPostStep<{ id?: string }>(
        "publish_reply",
        threadsUrl(path),
        accessToken,
        { creation_id: creationId },
      );
      return { id: String(published.id ?? "") };
    } catch (e) {
      lastError = e instanceof Error ? e : new Error(String(e));
      if (!isThreadsReplyRetryableError(lastError.message)) throw lastError;
    }
  }
  throw lastError ?? new Error("Failed to publish Threads reply");
}

async function tryDirectThreadsReplyPost(
  targetId: string,
  text: string,
  accessToken: string,
): Promise<{ id: string } | null> {
  try {
    const data = await threadsPost<{ id?: string }>(
      threadsUrl(`${targetId}/replies`),
      accessToken,
      { text, media_type: "TEXT" },
    );
    const id = String(data.id ?? "").trim();
    return id ? { id } : null;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    if (isThreadsReplyRetryableError(msg)) return null;
    throw e instanceof Error ? e : new Error(msg);
  }
}

async function tryContainerThreadsReplyPost(
  replyToId: string,
  text: string,
  accessToken: string,
  threadsUserId?: string,
): Promise<{ id: string } | null> {
  const createPaths = ["me/threads"];
  const explicitUserId = threadsUserId?.trim();
  if (explicitUserId) createPaths.push(`${explicitUserId}/threads`);

  let lastError: Error | null = null;
  for (const createPath of createPaths) {
    try {
      const container = await threadsPostStep<{ id?: string }>(
        "create_reply_container",
        threadsUrl(createPath),
        accessToken,
        {
          media_type: "TEXT",
          text,
          reply_to_id: replyToId,
        },
      );
      const creationId = String(container.id ?? "").trim();
      if (!creationId) throw new Error("Failed to create Threads reply container");
      return await publishThreadsReplyContainer(creationId, accessToken, threadsUserId);
    } catch (e) {
      lastError = e instanceof Error ? e : new Error(String(e));
      if (!isThreadsReplyRetryableError(lastError.message)) throw lastError;
      console.warn(`tryContainerThreadsReplyPost retry (${createPath}, reply_to_id=${replyToId}):`, lastError.message);
    }
  }
  if (lastError) throw lastError;
  return null;
}

export async function replyThreadsComment(
  mediaId: string,
  text: string,
  accessToken: string,
  replyToCommentId?: string,
  threadsUserId?: string,
): Promise<{ id: string }> {
  const postId = String(mediaId ?? "").trim();
  const commentId = replyToCommentId?.trim() ?? "";
  if (!postId || !text.trim()) throw new Error("Missing reply target");

  const targetIds = await buildThreadsReplyTargetIds(postId, commentId || undefined, accessToken);
  const attempts: string[] = [];
  let lastError: Error | null = null;

  for (const targetId of targetIds) {
    attempts.push(`POST /${targetId}/replies`);
    try {
      const direct = await tryDirectThreadsReplyPost(targetId, text, accessToken);
      if (direct?.id) return direct;
    } catch (e) {
      lastError = e instanceof Error ? e : new Error(String(e));
    }
  }

  for (const targetId of targetIds) {
    attempts.push(`reply_to_id=${targetId} (container+publish)`);
    try {
      const published = await tryContainerThreadsReplyPost(targetId, text, accessToken, threadsUserId);
      if (published?.id) return published;
    } catch (e) {
      lastError = e instanceof Error ? e : new Error(String(e));
      if (!isThreadsReplyRetryableError(lastError.message)) break;
    }
  }

  const detail = attempts.length > 0 ? ` Attempts: ${attempts.join("; ")}.` : "";
  const base = lastError?.message ?? "Failed to publish Threads reply";
  throw new Error(`${base}${detail}`);
}

const THREADS_EDIT_WINDOW_MS = 15 * 60 * 1000;

export function canEditThreadsComment(
  publishedAt: string | null | undefined,
  isOwner: boolean,
): boolean {
  if (!isOwner || !publishedAt) return false;
  const ms = Date.parse(publishedAt);
  if (!Number.isFinite(ms)) return false;
  return Date.now() - ms <= THREADS_EDIT_WINDOW_MS;
}

export async function hideThreadsReply(
  replyId: string,
  accessToken: string,
  hide = true,
): Promise<void> {
  const id = String(replyId ?? "").trim();
  if (!id) throw new Error("Missing reply id");
  await threadsPost(threadsUrl(`${id}/manage_reply`), accessToken, {
    hide: hide ? "true" : "false",
  });
}

export async function deleteThreadsMedia(
  mediaId: string,
  accessToken: string,
): Promise<{ deleted_id?: string }> {
  const id = String(mediaId ?? "").trim();
  if (!id) throw new Error("Missing media id");
  return threadsDelete<{ success?: boolean; deleted_id?: string }>(
    threadsUrl(id),
    accessToken,
  );
}

export async function editThreadsReply(
  args: {
    postMediaId: string;
    replyId: string;
    parentCommentId: string;
    text: string;
    accessToken: string;
    threadsUserId?: string;
    publishedAt?: string | null;
    isOwner?: boolean;
  },
): Promise<{ id: string }> {
  const postId = String(args.postMediaId ?? "").trim();
  const replyId = String(args.replyId ?? "").trim();
  const parentId = String(args.parentCommentId ?? "").trim();
  const text = String(args.text ?? "").trim();
  if (!postId || !replyId || !parentId || !text) {
    throw new Error("Missing edit target");
  }
  if (!canEditThreadsComment(args.publishedAt, Boolean(args.isOwner))) {
    throw new Error("Threads replies can only be edited within 15 minutes of posting.");
  }
  await deleteThreadsMedia(replyId, args.accessToken);
  return replyThreadsComment(postId, text, args.accessToken, parentId, args.threadsUserId);
}

export function computeThreadsEngagementRate(
  likes: number,
  comments: number,
  views: number,
  shares = 0,
): number | null {
  if (!Number.isFinite(views) || views <= 0) return null;
  const rate = ((likes + comments + shares) / views) * 100;
  return Number.isFinite(rate) ? rate : null;
}

export async function buildThreadsMetricsPostRows(
  posts: ThreadsPost[],
  accessToken: string,
  accountId: string,
): Promise<Array<{
  platform: "threads";
  account_id: string;
  content_id: string;
  posted_at: string | null;
  view_count: number;
  like_count: number;
  comment_count: number;
  share_count: number;
  reach: number;
  engagement_rate: number | null;
  caption: string | null;
  media_url: string | null;
  permalink: string | null;
}>> {
  const rows = [];
  for (const post of posts) {
    const insights = await fetchThreadInsights(post.id, accessToken);
    const likeCount = insights.likes;
    const commentCount = insights.replies;
    const viewCount = insights.views;
    const shareCount = insights.reposts + insights.quotes;
    rows.push({
      platform: "threads" as const,
      account_id: accountId,
      content_id: post.id,
      posted_at: post.timestamp,
      view_count: viewCount,
      like_count: likeCount,
      comment_count: commentCount,
      share_count: shareCount,
      reach: viewCount,
      engagement_rate: computeThreadsEngagementRate(likeCount, commentCount, viewCount, shareCount),
      caption: post.caption,
      media_url: post.media_url ?? post.thumbnail_url,
      permalink: post.permalink,
    });
  }
  return rows;
}

export function buildThreadsSummaryFromPosts(
  postRows: Array<{ view_count: number; like_count: number; comment_count: number; reach: number }>,
): {
  reach: number;
  views: number;
  engagement: number;
  totalLikes: number;
  totalComments: number;
} {
  const totalLikes = postRows.reduce((s, p) => s + p.like_count, 0);
  const totalComments = postRows.reduce((s, p) => s + p.comment_count, 0);
  let views = postRows.reduce((s, p) => s + p.view_count, 0);
  let reach = postRows.reduce((s, p) => s + p.reach, 0);
  if (reach > 0 && views < reach) views = reach;
  return { reach, views, engagement: totalLikes + totalComments, totalLikes, totalComments };
}

/** Threads API credentials — separate Meta app from META_APP_ID (Facebook/Instagram). */
export function threadsAppId(): string {
  return Deno.env.get("THREADS_APP_ID")?.trim() ?? "";
}

export function threadsAppSecret(): string {
  return Deno.env.get("THREADS_APP_SECRET")?.trim() ?? "";
}

export function isThreadsAppConfigured(): boolean {
  return !!threadsAppId() && !!threadsAppSecret();
}

export function threadsAppConfigErrorMessage(): string {
  return "Threads is not configured. Set THREADS_APP_ID and THREADS_APP_SECRET in Edge Function secrets.";
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptThreadsContentToken,
  encryptThreadsContentToken,
} from "./threadsContentConfigCrypto.ts";
import { refreshThreadsAccessToken, fetchThreadsGrantedPermissions, canThreadsTokenPublishReplies } from "./threadsContentApi.ts";
import { missingScopesForFeature, META_SCOPE_FEATURE_MAP } from "./metaPlatformScopes.ts";
import {
  isThreadsAppConfigured,
  threadsAppConfigErrorMessage,
  threadsAppId,
  threadsAppSecret,
} from "./threadsAppCredentials.ts";

export const threadsContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const THREADS_SCOPE_FEATURE_MAP = {
  threads_insights: META_SCOPE_FEATURE_MAP.threads_insights,
  threads_replies: META_SCOPE_FEATURE_MAP.threads_replies,
} as const;

export function threadsContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...threadsContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function parseThreadsGrantedScopes(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String);
  return [];
}

function mergeThreadsScopesIntoGranted(existing: unknown, threadsScopes: string[]): string[] {
  const parsed = parseThreadsGrantedScopes(existing);
  const withoutThreads = parsed.filter((s) => !s.toLowerCase().startsWith("threads_"));
  return [...new Set([...withoutThreads, ...threadsScopes])];
}

async function resolveLiveThreadsGrantedScopes(
  admin: SupabaseClient,
  organizationId: string,
  threadsUserId: string,
  storedGranted: string[],
): Promise<{ grantedScopes: string[]; canPublishReplies: boolean }> {
  const accessToken = await getThreadsAccessToken(admin, organizationId, threadsUserId);
  if (!accessToken) return { grantedScopes: storedGranted, canPublishReplies: false };

  const liveScopes = await fetchThreadsGrantedPermissions(
    accessToken,
    threadsAppId(),
    threadsAppSecret(),
  );
  const canPublishReplies = await canThreadsTokenPublishReplies(threadsUserId, accessToken);
  const effectiveLive = liveScopes;

  if (effectiveLive.length === 0) {
    return { grantedScopes: storedGranted, canPublishReplies };
  }

  const merged = mergeThreadsScopesIntoGranted(storedGranted, effectiveLive);
  const storedThreads = storedGranted.filter((s) => s.toLowerCase().startsWith("threads_")).sort().join(",");
  const mergedThreads = merged.filter((s) => s.toLowerCase().startsWith("threads_")).sort().join(",");
  if (storedThreads !== mergedThreads) {
    await admin
      .from("organization_instagram_accounts")
      .update({ granted_scopes: merged, updated_at: new Date().toISOString() })
      .eq("organization_id", organizationId)
      .eq("threads_user_id", threadsUserId)
      .eq("has_threads", true);
  }
  return { grantedScopes: merged, canPublishReplies };
}

export function isThreadsPlatformConfigured(): boolean {
  return isThreadsAppConfigured();
}

export function requireThreadsPlatformConfigured(): Response | null {
  if (!isThreadsPlatformConfigured()) {
    return threadsContentJson({ error: threadsAppConfigErrorMessage() }, 503);
  }
  return null;
}

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: threadsContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: threadsContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return threadsContentJson({ error: "Forbidden" }, 403);
  }
  return null;
}

export type ResolvedThreadsAccount = {
  threadsUserId: string;
  threadsUsername: string | null;
  threadsProfilePictureUrl: string | null;
  instagramBusinessAccountId: string;
  accountLabel: string;
  grantedScopes: string[];
};

export async function resolveThreadsContentAccount(
  admin: SupabaseClient,
  organizationId: string,
  accountId: string,
): Promise<ResolvedThreadsAccount | null> {
  const { data: byIg } = await admin
    .from("organization_instagram_accounts")
    .select("*")
    .eq("organization_id", organizationId)
    .eq("instagram_business_account_id", accountId)
    .eq("is_active", true)
    .eq("has_threads", true)
    .maybeSingle();

  let row = byIg;
  if (!row) {
    const { data: byThreadsRows } = await admin
      .from("organization_instagram_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("threads_user_id", accountId)
      .eq("is_active", true)
      .eq("has_threads", true)
      .order("updated_at", { ascending: false })
      .limit(1);
    row = (byThreadsRows ?? [])[0] ?? null;
  }

  if (!row) return null;
  const r = row as Record<string, unknown>;
  const threadsUserId = String(r.threads_user_id ?? "").trim();
  if (!threadsUserId) return null;

  return {
    threadsUserId,
    threadsUsername: typeof r.threads_username === "string" ? r.threads_username : null,
    threadsProfilePictureUrl: typeof r.threads_profile_picture_url === "string"
      ? r.threads_profile_picture_url
      : null,
    instagramBusinessAccountId: String(r.instagram_business_account_id ?? accountId),
    accountLabel: String(
      r.threads_username ?? r.instagram_username ?? r.instagram_name ?? threadsUserId,
    ),
    grantedScopes: parseThreadsGrantedScopes(r.granted_scopes),
  };
}

export async function getThreadsAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  threadsUserId: string,
): Promise<string | null> {
  const { data: tokenRows, error: tokenErr } = await admin
    .from("organization_instagram_accounts")
    .select("threads_access_token_enc, threads_token_expires_at")
    .eq("organization_id", organizationId)
    .eq("threads_user_id", threadsUserId)
    .eq("has_threads", true)
    .eq("is_active", true)
    .order("updated_at", { ascending: false })
    .limit(1);

  if (tokenErr) {
    console.error("getThreadsAccessToken query:", tokenErr.message);
    return null;
  }

  const row = (tokenRows ?? [])[0] as
    | { threads_access_token_enc: string; threads_token_expires_at: string | null }
    | undefined;
  if (!row?.threads_access_token_enc) return null;

  const expiresAtMs = row.threads_token_expires_at
    ? new Date(String(row.threads_token_expires_at)).getTime()
    : null;
  const needsRefresh = expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000;

  if (!needsRefresh) {
    try {
      return await decryptThreadsContentToken(String(row.threads_access_token_enc));
    } catch (e) {
      console.error("getThreadsAccessToken decrypt:", e);
    }
  }

  let currentToken: string;
  try {
    currentToken = await decryptThreadsContentToken(String(row.threads_access_token_enc));
  } catch (e) {
    console.error("getThreadsAccessToken refresh decrypt:", e);
    return null;
  }

  const refreshed = await refreshThreadsAccessToken(currentToken);
  if (!refreshed?.access_token) {
    return currentToken;
  }

  const now = new Date().toISOString();
  const accessEnc = await encryptThreadsContentToken(refreshed.access_token);
  const accessExpires = refreshed.expires_in
    ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
    : row.threads_token_expires_at;

  await admin
    .from("organization_instagram_accounts")
    .update({
      threads_access_token_enc: accessEnc,
      threads_token_expires_at: accessExpires,
      updated_at: now,
    })
    .eq("organization_id", organizationId)
    .eq("threads_user_id", threadsUserId);

  return refreshed.access_token;
}

export async function resolveOrgThreadsContent(
  admin: SupabaseClient,
  organizationId: string,
  accountIdParam?: string | null,
): Promise<{ accessToken: string; account: ResolvedThreadsAccount } | null> {
  let account: ResolvedThreadsAccount | null = null;

  if (accountIdParam?.trim()) {
    account = await resolveThreadsContentAccount(admin, organizationId, accountIdParam.trim());
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_instagram_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("has_threads", true)
      .order("updated_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (defaultRow) {
      const igId = String((defaultRow as Record<string, unknown>).instagram_business_account_id ?? "");
      if (igId) account = await resolveThreadsContentAccount(admin, organizationId, igId);
    }
  }

  if (!account) return null;

  const accessToken = await getThreadsAccessToken(admin, organizationId, account.threadsUserId);
  if (!accessToken) return null;

  return { accessToken, account };
}

export async function listThreadsContentAccounts(
  admin: SupabaseClient,
  organizationId: string,
): Promise<Array<{
  platform: "threads";
  account_id: string;
  threads_user_id: string;
  account_label: string;
  avatar_url: string | null;
  granted_scopes: string[];
  instagram_business_account_id: string;
  feature_status: Record<string, { ok: boolean; missing: string[] }>;
}>> {
  const { data: rows } = await admin
    .from("organization_instagram_accounts")
    .select(
      "instagram_business_account_id, threads_user_id, threads_username, instagram_username, instagram_name, threads_profile_picture_url, granted_scopes",
    )
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .eq("has_threads", true);

  const features = Object.keys(THREADS_SCOPE_FEATURE_MAP) as Array<keyof typeof THREADS_SCOPE_FEATURE_MAP>;

  const seenThreadsUserIds = new Set<string>();
  const liveScopesByThreadsUser = new Map<string, { grantedScopes: string[]; canPublishReplies: boolean }>();
  const out: Array<{
    platform: "threads";
    account_id: string;
    threads_user_id: string;
    account_label: string;
    avatar_url: string | null;
    granted_scopes: string[];
    instagram_business_account_id: string;
    feature_status: Record<string, { ok: boolean; missing: string[] }>;
  }> = [];

  for (const row of rows ?? []) {
    const r = row as Record<string, unknown>;
    const threadsUserId = String(r.threads_user_id ?? "").trim();
    if (!threadsUserId || seenThreadsUserIds.has(threadsUserId)) continue;
    seenThreadsUserIds.add(threadsUserId);

    const igId = String(r.instagram_business_account_id ?? "");
    let grantedScopes = parseThreadsGrantedScopes(r.granted_scopes);
    let canPublishReplies = false;
    if (!liveScopesByThreadsUser.has(threadsUserId)) {
      const resolved = await resolveLiveThreadsGrantedScopes(
        admin,
        organizationId,
        threadsUserId,
        grantedScopes,
      );
      grantedScopes = resolved.grantedScopes;
      canPublishReplies = resolved.canPublishReplies;
      liveScopesByThreadsUser.set(threadsUserId, resolved);
    } else {
      const cached = liveScopesByThreadsUser.get(threadsUserId)!;
      grantedScopes = cached.grantedScopes;
      canPublishReplies = cached.canPublishReplies;
    }
    const featureStatus = Object.fromEntries(
      features.map((f) => {
        if (f === "threads_replies" && canPublishReplies) {
          const missing = missingScopesForFeature(grantedScopes, f)
            .filter((scope) => scope !== "threads_content_publish");
          return [f, { ok: missing.length === 0, missing }];
        }
        return [f, {
          ok: missingScopesForFeature(grantedScopes, f).length === 0,
          missing: missingScopesForFeature(grantedScopes, f),
        }];
      }),
    );
    out.push({
      platform: "threads" as const,
      account_id: igId || threadsUserId,
      threads_user_id: threadsUserId,
      account_label: String(r.threads_username ?? r.instagram_username ?? r.instagram_name ?? threadsUserId),
      avatar_url: typeof r.threads_profile_picture_url === "string" ? r.threads_profile_picture_url : null,
      granted_scopes: grantedScopes,
      instagram_business_account_id: igId,
      feature_status: featureStatus,
    });
  }

  return out;
}

/**
 * AES-256-GCM encrypt/decrypt for per-org Threads user access tokens.
 * Key: THREADS_CONTENT_CONFIG_ENCRYPTION_KEY (or META_ADS_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("THREADS_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("META_ADS_CONFIG_ENCRYPTION_KEY")?.trim() ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export async function encryptThreadsContentToken(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

export async function decryptThreadsContentToken(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

