function formatBusinessCommentDeleteError(err: unknown): string {
  const base = err instanceof Error ? err.message : String(err);
  const lower = base.toLowerCase();
  if (
    lower.includes("40002")
    || lower.includes("invalid_params")
    || lower.includes("comment_id")
  ) {
    return (
      "Komentar ini tidak bisa dihapus di TikTok. "
      + "Hanya balasan/komentar dari akun Anda yang bisa dihapus — gunakan Hide untuk komentar pengguna lain."
    );
  }
  return base;
}

const TIKTOK_COMMENT_REPLY_MAX_LENGTH = 150;

function normalizeTikTokCommentReplyText(text: string): string {
  const trimmed = text.trim();
  if (!trimmed) throw new Error("Reply text is required");
  if (trimmed.length > TIKTOK_COMMENT_REPLY_MAX_LENGTH) {
    throw new Error(`Reply must be at most ${TIKTOK_COMMENT_REPLY_MAX_LENGTH} characters`);
  }
  return trimmed;
}

export async function replyTikTokComment(
  accessToken: string,
  args: { businessId: string; videoId: string; text: string; commentId: string },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<{ comment_id?: string }> {
  const parentCommentId = args.commentId.trim();
  const videoId = args.videoId.trim();
  if (!parentCommentId) throw new Error("comment_id is required to reply");
  if (!videoId) throw new Error("video_id is required to reply");

  const replyText = normalizeTikTokCommentReplyText(args.text);
  const businessBody: Record<string, unknown> = {
    business_id: args.businessId,
    account_id: videoId,
    video_id: videoId,
    comment_id: parentCommentId,
    text: replyText,
  };

  try {
    const data = await tiktokBusinessPost<{
      comment_id?: string | number;
      reply_id?: string | number;
    }>(
      accessToken,
      "/business/comment/reply/create/",
      businessBody,
    );
    const replyId = pickBusinessSnowflakeId(data.reply_id, data.comment_id);
    return {
      comment_id: replyId || undefined,
    };
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

function normalizeBusinessCommentId(commentId: string): string {
  const trimmed = commentId.trim();
  if (!trimmed) return trimmed;
  if (!/^\d{10,}$/.test(trimmed)) {
    throw new Error(
      `comment_id format is invalid (${trimmed}). Refresh the page to reload comments and try again.`,
    );
  }
  return trimmed;
}

function isRetryableBusinessCommentParamError(message: string): boolean {
  const lower = message.toLowerCase();
  return (
    lower.includes("40002")
    || lower.includes("invalid")
    || lower.includes("validate your param")
  );
}

async function postBusinessCommentActionWithFallbacks(
  accessToken: string,
  path: string,
  attempts: Record<string, unknown>[],
): Promise<void> {
  const errors: string[] = [];
  for (const body of attempts) {
    try {
      await tiktokBusinessPost<Record<string, never>>(accessToken, path, body);
      return;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      errors.push(msg);
      if (!isRetryableBusinessCommentParamError(msg)) {
        throw e;
      }
    }
  }
  throw new Error(errors[errors.length - 1] ?? `${path}: request failed`);
}

export async function deleteTikTokComment(
  accessToken: string,
  args: {
    businessId: string;
    videoId?: string;
    commentId: string;
    parentCommentId?: string;
  },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<void> {
  const commentId = normalizeBusinessCommentId(args.commentId);
  if (!commentId) throw new Error("comment_id is required to delete");
  const videoId = args.videoId?.trim() ?? "";
  const parentCommentId = args.parentCommentId?.trim() ?? "";

  const attempts: Record<string, unknown>[] = [
    { business_id: args.businessId, comment_id: commentId },
  ];
  if (videoId) {
    attempts.push(
      { business_id: args.businessId, video_id: videoId, comment_id: commentId },
      { business_id: args.businessId, item_id: videoId, comment_id: commentId },
      {
        business_id: args.businessId,
        account_id: videoId,
        video_id: videoId,
        comment_id: commentId,
      },
    );
    if (parentCommentId) {
      attempts.push({
        business_id: args.businessId,
        video_id: videoId,
        comment_id: commentId,
        parent_comment_id: parentCommentId,
      });
    }
  }

  try {
    await postBusinessCommentActionWithFallbacks(
      accessToken,
      "/business/comment/delete/",
      attempts,
    );
  } catch (e) {
    throw new Error(formatBusinessCommentDeleteError(e));
  }
}

export async function hideTikTokComment(
  accessToken: string,
  args: { businessId: string; commentId: string; videoId: string },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<void> {
  const commentId = normalizeBusinessCommentId(args.commentId);
  const videoId = args.videoId.trim();
  if (!commentId || !videoId) throw new Error("comment_id and video_id are required to hide");

  const attempts: Record<string, unknown>[] = [
    {
      business_id: args.businessId,
      video_id: videoId,
      comment_id: commentId,
      action: "HIDE",
    },
    {
      business_id: args.businessId,
      item_id: videoId,
      comment_id: commentId,
      action: "HIDE",
    },
  ];

  try {
    await postBusinessCommentActionWithFallbacks(
      accessToken,
      "/business/comment/hide/",
      attempts,
    );
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

export async function likeTikTokComment(
  accessToken: string,
  args: { businessId: string; commentId: string; action?: "LIKE" | "UNLIKE" },
  tokenKind: TikTokContentOAuthTokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit,
): Promise<void> {
  const commentId = normalizeBusinessCommentId(args.commentId);
  if (!commentId) throw new Error("comment_id is required to like");
  const action = args.action === "UNLIKE" ? "UNLIKE" : "LIKE";

  try {
    await tiktokBusinessPost<Record<string, never>>(
      accessToken,
      "/business/comment/like/",
      {
        business_id: args.businessId,
        comment_id: commentId,
        action,
      },
    );
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const tiktokContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const TIKTOK_CONTENT_API_BASE = "https://open.tiktokapis.com/v2";
export const TIKTOK_BUSINESS_API_BASE = "https://business-api.tiktok.com/open_api/v1.3";
export const TIKTOK_CONTENT_OAUTH_SCOPES =
  "user.info.basic,video.list,user.info.stats,comment.list,comment.list.manage,video.upload,video.publish";

export const TIKTOK_CONTENT_PUBLISH_SCOPES = ["video.upload", "video.publish"] as const;

/** Login Kit / Direct Post (developers.tiktok.com) — separate from business-api CONTENT credentials. */
export const TIKTOK_CONTENT_PUBLISH_OAUTH_SCOPES =
  "user.info.basic,video.upload,video.publish";

export type TikTokContentOAuthTokenKind = "login_kit" | "tt_user";

export const TIKTOK_CONTENT_OAUTH_TOKEN_KINDS = {
  loginKit: "login_kit" as TikTokContentOAuthTokenKind,
  ttUser: "tt_user" as TikTokContentOAuthTokenKind,
};

export const TIKTOK_CONTENT_COMMENT_SCOPES = ["comment.list", "comment.list.manage"] as const;

/** Union comma-separated OAuth scope strings (deduped, stable order). */
export function mergeTikTokContentOAuthScopes(
  ...scopeStrings: (string | null | undefined)[]
): string {
  const merged = new Set<string>();
  for (const raw of scopeStrings) {
    for (const part of String(raw ?? "").split(",")) {
      const trimmed = part.trim();
      if (trimmed) merged.add(trimmed);
    }
  }
  return [...merged].join(",");
}

/** TikTok often omits scopes in token JSON; merge stored + requested scopes. */
export function resolveTikTokContentOAuthScopes(stored: string | null | undefined): string {
  return mergeTikTokContentOAuthScopes(stored, TIKTOK_CONTENT_OAUTH_SCOPES);
}

export function tiktokContentScopesIncludeComments(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_COMMENT_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentScopesIncludePublish(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_PUBLISH_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...tiktokContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformTikTokContentOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

/** developers.tiktok.com app — Login Kit token exchange & publish OAuth start. */
export function readPlatformTikTokContentPublishOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_KEY")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

export function isTikTokContentPlatformConfigured(): boolean {
  return readPlatformTikTokContentOAuth() !== null;
}

export function isTikTokContentPublishPlatformConfigured(): boolean {
  return readPlatformTikTokContentPublishOAuth() !== null;
}

export function requireTikTokContentPlatformConfigured(): Response | null {
  if (!isTikTokContentPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok Content is not configured. Set TIKTOK_CONTENT_CLIENT_KEY and TIKTOK_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function requireTikTokContentPublishPlatformConfigured(): Response | null {
  if (!isTikTokContentPublishPlatformConfigured()) {
