export type YouTubeCommentApiRow = {
  id: string;
  video_id: string;
  text: string;
  author_display_name: string;
  author_avatar_url: string | null;
  author_channel_id: string | null;
  like_count: number;
  reply_count: number;
  parent_comment_id: string | null;
  published_at: string | null;
  is_channel_owner: boolean;
  /** commentThread id — required as parentId when replying to a top-level comment */
  thread_id?: string | null;
  /** Value for comments.insert snippet.parentId */
  reply_parent_id?: string | null;
  can_reply?: boolean;
};

type YouTubeCommentSnippet = {
  authorDisplayName?: unknown;
  authorProfileImageUrl?: unknown;
  authorChannelId?: unknown;
  textDisplay?: unknown;
  textOriginal?: unknown;
  publishedAt?: unknown;
  likeCount?: unknown;
  totalReplyCount?: unknown;
  parentId?: unknown;
  videoId?: unknown;
};

function coerceOptionalString(value: unknown): string | null {
  if (value == null) return null;
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed || null;
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value);
  }
  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    for (const key of ["channelId", "id", "value"]) {
      const nested = coerceOptionalString(record[key]);
      if (nested) return nested;
    }
  }
  return null;
}

function coerceString(value: unknown, fallback = ""): string {
  return coerceOptionalString(value) ?? fallback;
}

function mapYouTubeCommentSnippet(
  commentId: string,
  videoId: string,
  snippet: YouTubeCommentSnippet | undefined,
  channelId: string,
  parentCommentId: string | null,
): YouTubeCommentApiRow {
  const authorChannelId = coerceOptionalString(snippet?.authorChannelId);
  const text = coerceString(snippet?.textDisplay) || coerceString(snippet?.textOriginal);
  return {
    id: commentId,
    video_id: videoId,
    text,
    author_display_name: coerceString(snippet?.authorDisplayName, "YouTube user"),
    author_avatar_url: coerceOptionalString(snippet?.authorProfileImageUrl),
    author_channel_id: authorChannelId,
    like_count: Number(snippet?.likeCount ?? 0) || 0,
    reply_count: Number(snippet?.totalReplyCount ?? 0) || 0,
    parent_comment_id: parentCommentId,
    published_at: coerceOptionalString(snippet?.publishedAt),
    is_channel_owner: Boolean(authorChannelId && authorChannelId === channelId.trim()),
  };
}

type CommentThreadItem = {
  id?: string;
  snippet?: {
    topLevelComment?: { id?: string; snippet?: YouTubeCommentSnippet };
    videoId?: string;
    canReply?: boolean;
    totalReplyCount?: unknown;
  };
};

function isYouTubeCommentsAccessError(e: unknown): boolean {
  const msg = (e instanceof Error ? e.message : String(e)).toLowerCase();
  return msg.includes("http 403")
    || msg.includes("403")
    || msg.includes("insufficient")
    || msg.includes("forbidden")
    || msg.includes("commentsdisabled")
    || msg.includes("comments disabled");
}

export async function fetchGoogleTokenScopes(accessToken: string): Promise<string[]> {
  const res = await fetch(
    `https://www.googleapis.com/oauth2/v1/tokeninfo?access_token=${encodeURIComponent(accessToken)}`,
  );
  const json = await res.json().catch(() => ({})) as { scope?: string; error?: string };
  if (!res.ok || json.error) return [];
  return String(json.scope ?? "")
    .split(/\s+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

export async function verifyYouTubeVideoOwnedByChannel(
  accessToken: string,
  videoId: string,
  channelId: string,
): Promise<string | null> {
  const json = await youtubeDataGet<{
    items?: Array<{ snippet?: { channelId?: string; title?: string } }>;
  }>(accessToken, "/videos", {
    part: "snippet",
    id: videoId.trim(),
  });
  const ownerChannelId = String(json.items?.[0]?.snippet?.channelId ?? "").trim();
  if (!ownerChannelId) {
    return "Video not found or is not accessible with the connected Google account.";
  }
  if (ownerChannelId !== channelId.trim()) {
    return `This video belongs to YouTube channel ${ownerChannelId}, not the selected channel ${channelId}. Switch channel in the left sidebar.`;
  }
  return null;
}

function parseCommentThreadItems(
  items: CommentThreadItem[] | undefined,
  channelId: string,
  fallbackVideoId: string,
  filterVideoId?: string,
): YouTubeCommentApiRow[] {
  const all: YouTubeCommentApiRow[] = [];
  for (const thread of items ?? []) {
    const top = thread.snippet?.topLevelComment;
    const threadId = String(thread.id ?? "").trim();
    const topId = String(top?.id ?? "").trim();
    const vid = String(thread.snippet?.videoId ?? fallbackVideoId).trim();
    if (!topId) continue;
    if (filterVideoId && vid !== filterVideoId.trim()) continue;
    const totalReplyCount = Number(thread.snippet?.totalReplyCount ?? 0) || 0;
    all.push({
      ...mapYouTubeCommentSnippet(topId, vid, top?.snippet, channelId, null),
      reply_count: totalReplyCount,
      thread_id: threadId || null,
      // YouTube expects commentThread id as parentId for top-level replies.
      reply_parent_id: threadId || topId,
      can_reply: thread.snippet?.canReply !== false,
    });
  }
  return all;
}

async function fetchCommentThreadPages(
  accessToken: string,
  paramsBase: Record<string, string>,
  channelId: string,
  videoId: string,
  maxResults: number,
  options?: { filterVideoId?: string; maxPages?: number },
): Promise<YouTubeCommentApiRow[]> {
  const all: YouTubeCommentApiRow[] = [];
  const filterVideoId = options?.filterVideoId;
  const maxPages = options?.maxPages ?? 20;
  let pageToken = "";
  let emptyFilteredPages = 0;

  for (let page = 0; page < maxPages; page++) {
    const params: Record<string, string> = {
      part: "snippet",
      textFormat: "plainText",
      maxResults: String(Math.min(maxResults, 100)),
      ...paramsBase,
    };
    if (pageToken) params.pageToken = pageToken;

    const json = await youtubeDataGet<{
      items?: CommentThreadItem[];
      nextPageToken?: string;
    }>(accessToken, "/commentThreads", params);

    const pageRows = parseCommentThreadItems(json.items, channelId, videoId, filterVideoId);
    if (filterVideoId) {
      if (pageRows.length === 0) {
        emptyFilteredPages += 1;
      } else {
        emptyFilteredPages = 0;
        all.push(...pageRows);
      }
      if (emptyFilteredPages >= 3 && all.length > 0) break;
    } else {
      all.push(...pageRows);
    }

    if (!json.nextPageToken) break;
    pageToken = json.nextPageToken;
    if (!filterVideoId && all.length >= maxResults) break;
  }

  return all;
}

export async function fetchYouTubeCommentThreads(
  accessToken: string,
  channelId: string,
  videoId: string,
  maxResults = 100,
): Promise<YouTubeCommentApiRow[]> {
  const trimmedVideoId = videoId.trim();
  const trimmedChannelId = channelId.trim();

  const ownershipIssue = await verifyYouTubeVideoOwnedByChannel(
    accessToken,
    trimmedVideoId,
    trimmedChannelId,
  ).catch(() => null);
  if (ownershipIssue) {
    throw new Error(ownershipIssue);
  }

  try {
    return await fetchCommentThreadPages(
      accessToken,
      { videoId: trimmedVideoId, order: "time" },
      trimmedChannelId,
      trimmedVideoId,
      maxResults,
    );
  } catch (e) {
    if (!isYouTubeCommentsAccessError(e)) throw e;
    return await fetchCommentThreadPages(
      accessToken,
      { allThreadsRelatedToChannelId: trimmedChannelId, order: "time" },
      trimmedChannelId,
      trimmedVideoId,
      maxResults,
      { filterVideoId: trimmedVideoId, maxPages: 25 },
    );
  }
}

export async function fetchYouTubeCommentReplies(
  accessToken: string,
  channelId: string,
  parentCommentId: string,
  maxResults = 100,
): Promise<YouTubeCommentApiRow[]> {
  const all: YouTubeCommentApiRow[] = [];
  let pageToken = "";

  for (let page = 0; page < 20; page++) {
    const params: Record<string, string> = {
      part: "snippet",
      parentId: parentCommentId.trim(),
      textFormat: "plainText",
      maxResults: String(Math.min(maxResults, 100)),
    };
    if (pageToken) params.pageToken = pageToken;

    const json = await youtubeDataGet<{
      items?: Array<{ id?: string; snippet?: YouTubeCommentSnippet }>;
      nextPageToken?: string;
    }>(accessToken, "/comments", params);

    for (const item of json.items ?? []) {
      const id = String(item.id ?? "").trim();
      if (!id) continue;
      const vid = String(item.snippet?.videoId ?? "").trim();
      const snippet = item.snippet;
      all.push({
        ...mapYouTubeCommentSnippet(
          id,
          vid,
          snippet,
          channelId,
          coerceOptionalString(snippet?.parentId) ?? parentCommentId.trim(),
        ),
        reply_parent_id: id,
        can_reply: true,
      });
    }

    if (!json.nextPageToken) break;
    pageToken = json.nextPageToken;
  }

  return all;
}

async function lookupCommentThreadIdByTopLevelComment(
  accessToken: string,
  channelId: string,
  videoId: string,
  topLevelCommentId: string,
): Promise<string | null> {
  const needle = topLevelCommentId.trim();
  if (!needle) return null;
  try {
    const threads = await fetchCommentThreadPages(
      accessToken,
      { videoId: videoId.trim(), order: "time" },
      channelId.trim(),
      videoId.trim(),
      100,
      { maxPages: 15 },
    );
    for (const row of threads) {
      if (row.id === needle) {
        return row.thread_id ?? null;
      }
    }
  } catch (e) {
    console.warn("lookupCommentThreadIdByTopLevelComment:", e instanceof Error ? e.message : e);
  }
  return null;
}

async function insertYouTubeCommentReplyOnce(
  accessToken: string,
  parentId: string,
  text: string,
): Promise<{ id: string; snippet?: YouTubeCommentSnippet }> {
  return youtubeDataPost<{ id?: string; snippet?: YouTubeCommentSnippet }>(
    accessToken,
    "/comments",
    { part: "snippet" },
    {
      snippet: {
        parentId: parentId.trim(),
        textOriginal: text.trim(),
      },
    },
  );
}

export async function insertYouTubeCommentReply(
  accessToken: string,
  channelId: string,
  videoId: string,
  targetCommentId: string,
  text: string,
  opts?: {
    threadId?: string | null;
    /** Top-level comment id in the thread (required when replying to a nested reply). */
    topLevelCommentId?: string | null;
  },
): Promise<YouTubeCommentApiRow> {
  const trimmedVideoId = videoId.trim();
  const trimmedChannelId = channelId.trim();
  const trimmedTargetId = targetCommentId.trim();
  const trimmedText = text.trim();
  if (!trimmedVideoId || !trimmedTargetId || !trimmedText) {
    throw new Error("Missing video_id, parent comment, or reply text");
  }

  const ownershipIssue = await verifyYouTubeVideoOwnedByChannel(
    accessToken,
    trimmedVideoId,
    trimmedChannelId,
  );
  if (ownershipIssue) {
    throw new Error(ownershipIssue);
  }

  // YouTube comments.insert only supports replies to top-level comments.
  // parentId must always be the commentThread id, even when the UI targets a nested reply.
  const topLevelCommentId = String(opts?.topLevelCommentId ?? "").trim() || trimmedTargetId;
  let threadId = String(opts?.threadId ?? "").trim();
  if (!threadId) {
    threadId = await lookupCommentThreadIdByTopLevelComment(
      accessToken,
      trimmedChannelId,
      trimmedVideoId,
      topLevelCommentId,
    ) ?? "";
  }
  if (!threadId) {
    throw new Error("Could not resolve comment thread for this reply. Refresh comments and try again.");
  }

  const json = await insertYouTubeCommentReplyOnce(
    accessToken,
    threadId,
    trimmedText,
  );
  const id = String(json.id ?? "").trim();
  if (!id) {
    throw new Error("YouTube did not return a comment id for the reply");
  }
  return {
    ...mapYouTubeCommentSnippet(
      id,
      trimmedVideoId,
      json.snippet,
      trimmedChannelId,
      topLevelCommentId,
    ),
    thread_id: threadId,
    reply_parent_id: threadId,
    can_reply: true,
  };
}

export async function insertYouTubeTopLevelComment(
  accessToken: string,
  channelId: string,
  videoId: string,
  text: string,
): Promise<YouTubeCommentApiRow> {
  const trimmedVideoId = videoId.trim();
  const trimmedChannelId = channelId.trim();
  const trimmedText = text.trim();
  if (!trimmedVideoId || !trimmedText) {
    throw new Error("Missing video_id or comment text");
  }

  const ownershipIssue = await verifyYouTubeVideoOwnedByChannel(
    accessToken,
    trimmedVideoId,
    trimmedChannelId,
  );
  if (ownershipIssue) {
    throw new Error(ownershipIssue);
  }

  const json = await youtubeDataPost<CommentThreadItem>(
    accessToken,
    "/commentThreads",
    { part: "snippet" },
    {
      snippet: {
        channelId: trimmedChannelId,
        videoId: trimmedVideoId,
        topLevelComment: {
          snippet: { textOriginal: trimmedText },
        },
      },
    },
  );
  const row = parseCommentThreadItems([json], trimmedChannelId, trimmedVideoId)[0];
  if (!row) {
    throw new Error("YouTube did not return the new comment");
  }
  return row;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptYouTubeContentToken,
  encryptYouTubeContentToken,
} from "./youtubeContentConfigCrypto.ts";
import { readPlatformYouTubeContentOAuth } from "./youtubeContentAuth.ts";
import { refreshYouTubeContentAccessToken } from "./youtubeContentApi.ts";

export type YouTubeContentAccountRow = {
  id: string;
  organization_id: string;
  channel_id: string;
  label: string;
  display_name: string | null;
  thumbnail_url: string | null;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
};

export async function getYouTubeContentAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  channelId: string,
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_youtube_content_connection_tokens")
    .select("access_token_enc, refresh_token_enc, access_token_expires_at")
    .eq("organization_id", organizationId)
    .eq("channel_id", channelId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000;

  if (!needsRefresh) {
    try {
      return await decryptYouTubeContentToken(String(tokenRow.access_token_enc));
    } catch (e) {
      console.error("getYouTubeContentAccessToken decrypt:", e);
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptYouTubeContentToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getYouTubeContentAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformYouTubeContentOAuth();
  const refreshed = oauth
    ? await refreshYouTubeContentAccessToken(oauth.clientId, oauth.clientSecret, refreshToken)
    : null;

  if (!refreshed?.access_token) {
    try {
      return await decryptYouTubeContentToken(String(tokenRow.access_token_enc));
    } catch {
      return null;
    }
  }

  const now = new Date().toISOString();
  const accessEnc = await encryptYouTubeContentToken(refreshed.access_token);
  const refreshEnc = refreshed.refresh_token
    ? await encryptYouTubeContentToken(refreshed.refresh_token)
    : String(tokenRow.refresh_token_enc);
  const accessExpires = refreshed.expires_in
    ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
    : tokenRow.access_token_expires_at;

  await admin.from("organization_youtube_content_connection_tokens").update({
    access_token_enc: accessEnc,
    refresh_token_enc: refreshEnc,
    access_token_expires_at: accessExpires,
    updated_at: now,
  }).eq("organization_id", organizationId).eq("channel_id", channelId);

  return refreshed.access_token;
}

export async function resolveOrgYouTubeContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  channelIdParam?: string | null,
): Promise<{ accessToken: string; account: YouTubeContentAccountRow } | null> {
  let account: YouTubeContentAccountRow | null = null;

  if (channelIdParam) {
    const { data: row } = await admin
      .from("organization_youtube_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("channel_id", channelIdParam.trim())
      .maybeSingle();
    if (row) account = row as YouTubeContentAccountRow;
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_youtube_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("is_default", true)
      .maybeSingle();
    account = (defaultRow as YouTubeContentAccountRow | null) ?? null;
  }

  if (!account) {
    const { data: firstRow } = await admin
      .from("organization_youtube_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })
      .limit(1)
      .maybeSingle();
    account = (firstRow as YouTubeContentAccountRow | null) ?? null;
  }

  if (!account?.channel_id) return null;

  const accessToken = await getYouTubeContentAccessToken(admin, organizationId, account.channel_id);
  if (!accessToken) return null;

  return { accessToken, account };
}

/**
 * AES-256-GCM for YouTube Content OAuth tokens.
 * Key: YOUTUBE_CONTENT_CONFIG_ENCRYPTION_KEY (or GOOGLE_ADS_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("YOUTUBE_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("GOOGLE_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptYouTubeContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptYouTubeContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

