export type LinkedInContentAccountKind = "organization" | "person";
export type LinkedInPublishScopeFeature = "publish" | "memberPublish";

export type LinkedInContentAccountRow = {
  id: string;
  organization_id: string;
  page_id: string;
  account_kind?: LinkedInContentAccountKind | string | null;
  label: string;
  display_name: string | null;
  thumbnail_url: string | null;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
  granted_scopes?: unknown;
};

export function isLinkedInPersonAccount(
  account: Pick<LinkedInContentAccountRow, "account_kind"> | null | undefined,
): boolean {
  return String(account?.account_kind ?? "organization") === "person";
}

export function normalizeLinkedInAccountKind(
  raw: unknown,
): LinkedInContentAccountKind {
  return String(raw ?? "").trim() === "person" ? "person" : "organization";
}

export function linkedInPublishScopeFeature(
  accountKind: LinkedInContentAccountKind,
): LinkedInPublishScopeFeature {
  return accountKind === "person" ? "memberPublish" : "publish";
}

export type LinkedInPublishAccount = {
  accessToken: string;
  pageId: string;
  accountKind: LinkedInContentAccountKind;
  authorUrn: string;
  accountLabel: string;
  grantedScopes: string[];
  scopeFeature: LinkedInPublishScopeFeature;
};

/** Resolve token + author URN for Reel/carousel publish (org page or personal member). */
export async function resolveLinkedInPublishAccount(
  admin: SupabaseClient,
  organizationId: string,
  pageIdParam: string,
): Promise<LinkedInPublishAccount | null> {
  const pageId = String(pageIdParam ?? "").trim();
  if (!pageId) return null;

  const { data: row } = await admin
    .from("organization_linkedin_content_accounts")
    .select("page_id, account_kind, label, display_name, granted_scopes, is_active")
    .eq("organization_id", organizationId)
    .eq("page_id", pageId)
    .eq("is_active", true)
    .maybeSingle();
  if (!row?.page_id) return null;

  const accountKind = normalizeLinkedInAccountKind(
    (row as { account_kind?: string }).account_kind,
  );
  const accessToken = await getLinkedInContentAccessToken(admin, organizationId, pageId);
  if (!accessToken) return null;

  const grantedScopes = parseLinkedInGrantedScopes(
    (row as { granted_scopes?: unknown }).granted_scopes,
  );
  const accountLabel = String(
    (row as { display_name?: string | null }).display_name ??
      (row as { label?: string | null }).label ??
      "LinkedIn",
  );

  return {
    accessToken,
    pageId,
    accountKind,
    authorUrn: buildLinkedInAuthorUrn(accountKind, pageId),
    accountLabel,
    grantedScopes,
    scopeFeature: linkedInPublishScopeFeature(accountKind),
  };
}

export function linkedInPublishScopesOk(
  grantedScopes: string[],
  accountKind: LinkedInContentAccountKind,
): boolean {
  return missingLinkedInScopesForFeature(
    grantedScopes,
    linkedInPublishScopeFeature(accountKind),
  ).length === 0;
}

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
};

export async function getLinkedInContentAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  options?: { forceRefresh?: boolean },
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_linkedin_content_connection_tokens")
    .select("access_token_enc, refresh_token_enc, access_token_expires_at")
    .eq("organization_id", organizationId)
    .eq("page_id", pageId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = options?.forceRefresh === true ||
    (expiresAtMs != null &&
      Number.isFinite(expiresAtMs) &&
      expiresAtMs < Date.now() + 60_000);

  if (!needsRefresh) {
    try {
      return await decryptLinkedInContentToken(String(tokenRow.access_token_enc));
    } catch (e) {
      console.error("getLinkedInContentAccessToken decrypt:", e);
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptLinkedInContentToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getLinkedInContentAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformLinkedInContentOAuth();
  const refreshed = oauth
    ? await refreshLinkedInContentAccessToken(oauth.clientId, oauth.clientSecret, refreshToken)
    : null;

  if (!refreshed?.access_token) {
    try {
      return await decryptLinkedInContentToken(String(tokenRow.access_token_enc));
    } catch {
      return null;
    }
  }

  const now = new Date().toISOString();
  const accessEnc = await encryptLinkedInContentToken(refreshed.access_token);
  const refreshEnc = refreshed.refresh_token
    ? await encryptLinkedInContentToken(refreshed.refresh_token)
    : String(tokenRow.refresh_token_enc);
  const accessExpires = refreshed.expires_in
    ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
    : tokenRow.access_token_expires_at;

  await admin.from("organization_linkedin_content_connection_tokens").update({
    access_token_enc: accessEnc,
    refresh_token_enc: refreshEnc,
    access_token_expires_at: accessExpires,
    updated_at: now,
  }).eq("organization_id", organizationId).eq("page_id", pageId);

  return refreshed.access_token;
}

/** Org Company Page metrics/comments only — never returns person accounts. */
export async function resolveOrgLinkedInContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  pageIdParam?: string | null,
): Promise<{ accessToken: string; account: LinkedInContentAccountRow } | null> {
  const resolved = await resolveLinkedInContentForMetrics(admin, organizationId, pageIdParam, {
    allowPerson: false,
  });
  return resolved;
}

/** Performance metrics: organization pages and (when allowPerson) personal profiles. */
export async function resolveLinkedInContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  pageIdParam?: string | null,
  options?: { allowPerson?: boolean },
): Promise<{ accessToken: string; account: LinkedInContentAccountRow } | null> {
  const allowPerson = options?.allowPerson === true;
  let account: LinkedInContentAccountRow | null = null;

  if (pageIdParam) {
    const { data: row } = await admin
      .from("organization_linkedin_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("page_id", pageIdParam.trim())
      .maybeSingle();
    if (row) account = row as LinkedInContentAccountRow;
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_linkedin_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("is_default", true)
      .eq("account_kind", "organization")
      .maybeSingle();
    account = (defaultRow as LinkedInContentAccountRow | null) ?? null;
  }

  if (!account) {
    const { data: firstRow } = await admin
      .from("organization_linkedin_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("account_kind", "organization")
      .order("sort_order", { ascending: true })
      .limit(1)
      .maybeSingle();
    account = (firstRow as LinkedInContentAccountRow | null) ?? null;
  }

  if (!account?.page_id) return null;
  if (isLinkedInPersonAccount(account) && !allowPerson) return null;

  const accessToken = await getLinkedInContentAccessToken(admin, organizationId, account.page_id);
  if (!accessToken) return null;

  return { accessToken, account };
}

/**
 * AES-256-GCM for LinkedIn Content OAuth tokens.
 * Key: LINKEDIN_CONTENT_CONFIG_ENCRYPTION_KEY (or GOOGLE_ADS_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("LINKEDIN_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("GOOGLE_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptLinkedInContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptLinkedInContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const linkedinContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

/** Organic insights, comments, and page admin (Community Management API required). */
export const LINKEDIN_CONTENT_OAUTH_SCOPES_DEFAULT = [
  "r_organization_social",
  "r_organization_social_feed",
  "w_organization_social_feed",
  "w_organization_social",
  "rw_organization_admin",
].join(" ");

/**
 * Personal profile connect (Share on LinkedIn). Used only when connect_kind=person.
 * Do not merge into LINKEDIN_CONTENT_OAUTH_SCOPES_DEFAULT (page path stays org-only).
 */
/**
 * Only request scopes LinkedIn Auth tab accepts on Content Insight.
 * `r_member_social` / `r_member_postAnalytics` caused invalid_scope (not grantable yet) —
 * keep them in LINKEDIN_SCOPE_FEATURE_MAP.memberInsights for status UI, not in authorize URL.
 */
export const LINKEDIN_CONTENT_MEMBER_OAUTH_SCOPES_DEFAULT = [
  "w_member_social",
  "r_basicprofile",
].join(" ");

export type LinkedInContentConnectKind = "organization" | "person";

export const LINKEDIN_SCOPE_FEATURE_MAP = {
  insights: ["r_organization_social"] as const,
  comments: ["r_organization_social_feed", "w_organization_social_feed"] as const,
  publish: ["w_organization_social"] as const,
  /** Personal profile publish (Share on LinkedIn). Requested via member OAuth only. */
  memberPublish: ["w_member_social"] as const,
  /** Personal profile insights (Posts finder + memberCreatorPostAnalytics). */
  memberInsights: ["r_member_social", "r_member_postAnalytics"] as const,
  pages: ["rw_organization_admin"] as const,
} as const;

export function parseLinkedInGrantedScopes(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String);
  if (typeof raw === "string") {
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch {
      return raw.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
    }
  }
  return [];
}

export function missingLinkedInScopesForFeature(
  granted: string[],
  feature: keyof typeof LINKEDIN_SCOPE_FEATURE_MAP,
): string[] {
  const required = LINKEDIN_SCOPE_FEATURE_MAP[feature];
  const grantedSet = new Set(granted.map((s) => s.toLowerCase()));
  return required.filter((s) => !grantedSet.has(s.toLowerCase()));
}

export function linkedinContentOAuthScopes(): string {
  const explicit = Deno.env.get("LINKEDIN_CONTENT_OAUTH_SCOPES")?.trim();
  return explicit || LINKEDIN_CONTENT_OAUTH_SCOPES_DEFAULT;
}

export function linkedinContentMemberOAuthScopes(): string {
  const explicit = Deno.env.get("LINKEDIN_CONTENT_MEMBER_OAUTH_SCOPES")?.trim();
  return explicit || LINKEDIN_CONTENT_MEMBER_OAUTH_SCOPES_DEFAULT;
}

export function parseLinkedInConnectKind(raw: unknown): LinkedInContentConnectKind {
  return String(raw ?? "").trim() === "person" ? "person" : "organization";
}

export function linkedinContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...linkedinContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformLinkedInContentOAuth(): { clientId: string; clientSecret: string } | null {
  const clientId = Deno.env.get("LINKEDIN_CONTENT_CLIENT_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("LINKEDIN_CONTENT_CLIENT_SECRET")?.trim() ?? "";
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret };
}

export function isLinkedInContentPlatformConfigured(): boolean {
  return readPlatformLinkedInContentOAuth() !== null;
}

export function requireLinkedInContentPlatformConfigured(): Response | null {
  if (!isLinkedInContentPlatformConfigured()) {
    return linkedinContentJson(
      {
        error:
          "LinkedIn Content is not configured. Set LINKEDIN_CONTENT_CLIENT_ID and LINKEDIN_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function linkedinContentOAuthRedirectUri(): string {
  const explicit = Deno.env.get("LINKEDIN_CONTENT_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/linkedin-content-api`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const LINKEDIN_CONTENT_OAUTH_RETURN_PATHS = new Set([
  "/digital-marketing/social-media-performance/linkedin/settings",
]);

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: linkedinContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: linkedinContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelContentAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelContentAdmin(admin, userId, organizationId);
  if (!ok) return linkedinContentJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return linkedinContentJson({ error: "Forbidden" }, 403);
  }
  return null;
}

